// kittu-compat:file
// Generated by scripts/rebrand-kittu.mjs; legacy markers are intentional.
import { describe, expect, it } from "vitest";
import { appendMarker, KITTU_PR_MARKER } from "../src/hooks/PrMarkerHook.js";

describe("PR marker compatibility", () => {
	it("leaves a body with the pre-rebrand marker untouched", () => {
		const body = "Summary\n\n<!-- generated-by-cyrus -->";
		expect(appendMarker(body)).toBe(body);
	});

	it("leaves a body with the new marker untouched", () => {
		const body = `Summary\n\n${KITTU_PR_MARKER}`;
		expect(appendMarker(body)).toBe(body);
	});

	it("appends only the new marker to an unmarked body", () => {
		const out = appendMarker("Summary");
		expect(out).toBe(`Summary\n\n${KITTU_PR_MARKER}`);
		expect(out).not.toContain("cyrus");
	});
});
